def is_unreplied(messages,self_id):
  li=lo=None
  for m in sorted(messages,key=lambda x:x.get("created_time") or "",reverse=True):
    fid=(m.get("from") or {}).get("id")
    if fid==self_id and lo is None: lo=m
    if fid and fid!=self_id and li is None: li=m
  return bool(li and (not lo or (li.get("created_time") or "")>(lo.get("created_time") or "")))
